 async function sendResponse(id,answer,submit){const r=await SearchRecords.liveCall('y10_search_sort_response',{p_round:id,p_answer:answer,p_submit:submit});if(n){n.discussions??={};n.discussions[id]??={};n.discussions[id][submit?'submitted':'draft']=answer;n.discussions[id].history??=[];n.discussions[id].history.push({answer,submitted:submit,receivedAt:r.server_now});if(submit)n.discussions[id].submittedAt=r.server_now;persist();SearchRecords.record('attempt',page().id,{discussion:id,answer,submitted:submit,receivedAt:r.server_now});}return r;}
